const msg = $('Telegram Trigger').first().json.message;
const chatId = msg.chat.id;
let contentType = 'text', rawContent = '', photoFileId = null;
const caption = msg.caption || '';
if (msg.text) {
  const urls = msg.text.match(/(https?:\/\/[^\s]+)/g);
  if (urls) { contentType = 'url'; rawContent = urls[0]; }
  else { contentType = 'text'; rawContent = msg.text; }
} else if (msg.photo) {
  photoFileId = msg.photo[msg.photo.length - 1].file_id;
  const urls = caption.match(/(https?:\/\/[^\s]+)/g);
  if (urls) {
    contentType = 'url';
    rawContent = urls[0];
  } else {
    contentType = 'photo';
    rawContent = caption;
  }
} else if (msg.caption) {
  const urls = msg.caption.match(/(https?:\/\/[^\s]+)/g);
  if (urls) { contentType = 'url'; rawContent = urls[0]; }
  else { contentType = 'text'; rawContent = msg.caption; }
}
const jinaFetchUrl = contentType === 'url'
  ? 'https://r.jina.ai/' + rawContent
  : 'https://r.jina.ai/https://example.com';
return [{ json: { contentType, rawContent, photoFileId, caption, chatId, jinaFetchUrl } }];

// $input viene del nodo Jina Fetch (HTTP Request)
// Los datos originales los leemos de Detectar Contenido
const jinaInput = $input.first().json;
const d = $('Detectar Contenido').first().json;

let title = '', metaDesc = '', bodyText = '', featuredImage = '', externalPhotoUrl = '';
let source = 'Telegram', sourceUrl = '';

if (d.contentType === 'url') {

  // Leer respuesta de Jina.ai (puede venir como JSON o como texto plano)
  const jinaData = jinaInput.data || jinaInput;
  const jinaContent = jinaData.content || jinaData.text || '';

  if (jinaContent.length > 100) {
    title = jinaData.title || '';
    metaDesc = jinaData.description || '';
    bodyText = jinaContent.substring(0, 8000);

    // Extraer imagen del articulo del contenido markdown
    // Busca todas las URLs de imagen y elige la primera que sea del directorio /uploads/ y no sea logo/gif
    const isArticleImg = (url) =>
      /\.(jpg|jpeg|png|webp)/i.test(url) &&
      !/gif|cropped|icon|weather|pixel\.wp|spinner|banner|placeholder/i.test(url);

    // Primero intentar desde el objeto images de Jina
    const jinaImgs = jinaData.images || {};
    const fromImgsObj = Object.keys(jinaImgs).find(k => k.startsWith('http') && isArticleImg(k) && k.includes('uploads'));

    // Si no, buscar en el texto markdown: ![alt](url)
    let fromText = '';
    if (!fromImgsObj) {
      const allInline = [...jinaContent.matchAll(/!\[.*?\]\((https?:\/\/[^\s)]+)\)/g)];
      fromText = (allInline.map(m => m[1]).find(u => isArticleImg(u) && u.includes('uploads'))) || '';
      // Ultimo fallback: cualquier imagen valida aunque no tenga /uploads/
      if (!fromText) {
        fromText = (allInline.map(m => m[1]).find(u => isArticleImg(u))) || '';
      }
    }

    featuredImage = fromImgsObj || fromText || '';
  } else {
    // Respuesta inesperada — guardar para debug
    bodyText = JSON.stringify(jinaInput).substring(0, 2000);
  }

  sourceUrl = d.rawContent;
  if (d.rawContent.includes('distritointerior')) source = 'Distrito Interior';
  else if (d.rawContent.includes('diariodemocracia')) source = 'Diario Democracia';
  else if (d.rawContent.includes('facebook.com')) source = 'Facebook';
  else if (d.rawContent.includes('infobae')) source = 'Infobae';
  else if (d.rawContent.includes('clarin')) source = 'Clarin';
  else if (d.rawContent.includes('lanacion')) source = 'La Nacion';
  else if (d.rawContent.includes('pagina12')) source = 'Pagina 12';
  else if (d.rawContent.includes('ambito')) source = 'Ambito';
  else if (d.rawContent.includes('telam')) source = 'Telam';

  if (d.photoFileId) {
    try {
      const fileResp = await fetch('https://api.telegram.org/bot8495011193:AAHMwEXl9RsWvxBLr3_WAJQthTQApZQCN4w/getFile?file_id=' + d.photoFileId);
      const fileData = await fileResp.json();
      externalPhotoUrl = 'https://api.telegram.org/file/bot8495011193:AAHMwEXl9RsWvxBLr3_WAJQthTQApZQCN4w/' + (fileData.result?.file_path || '');
    } catch(e) {}
  }

} else if (d.contentType === 'photo') {
  title = d.caption || 'Noticia con imagen';
  bodyText = d.caption || '';
  metaDesc = d.caption || '';
  source = 'WhatsApp / Telegram';
  try {
    const fileResp = await fetch('https://api.telegram.org/bot8495011193:AAHMwEXl9RsWvxBLr3_WAJQthTQApZQCN4w/getFile?file_id=' + d.photoFileId);
    const fileData = await fileResp.json();
    externalPhotoUrl = 'https://api.telegram.org/file/bot8495011193:AAHMwEXl9RsWvxBLr3_WAJQthTQApZQCN4w/' + (fileData.result?.file_path || '');
  } catch(e) {}
} else {
  title = d.rawContent.substring(0, 100);
  bodyText = d.rawContent;
  source = 'Redaccion propia';
}

const scrapeOk = bodyText.length > 80;
const rawNewsText = 'TITULO: ' + title + '\n\nDESCRIPCION: ' + metaDesc + '\n\nCONTENIDO:\n' + bodyText;

return [{ json: { title, metaDesc, bodyText, featuredImage, externalPhotoUrl, source, sourceUrl, rawNewsText, scrapeOk, chatId: d.chatId, contentType: d.contentType } }];

const d = $input.first().json;

const instruccion = `INSTRUCCION: Resumí FIELMENTE esta noticia para redes sociales. NO inventes ni agregues datos que no estén en el texto. Si el contenido es escaso, basate solo en el titulo.

Devolvé UNICAMENTE este JSON (sin texto adicional):
{"titulo": "titulo fiel al articulo, max 80 caracteres", "caption_instagram": "resumen fiel con emoji al inicio, max 150 palabras, hashtags al final: #GeneralPinto #BsAs #Argentina + hashtags del tema", "caption_facebook": "resumen informativo fiel, 150-200 palabras, tono periodistico", "prompt_imagen": "descripcion en ingles de imagen ilustrativa para el articulo, sin texto en la imagen, realista, max 80 palabras", "categoria": "Politica|Economia|Sociedad|Deportes|Cultura|Salud|Seguridad|Educacion|Tecnologia"}`;

const aviso = d.scrapeOk ? '' : '\n[AVISO: el articulo no pudo cargarse completamente, usar solo el titulo y la descripcion disponibles]';

const userContent = 'Fuente: ' + d.source + aviso + '\n\n' + d.rawNewsText + '\n\n' + instruccion;
return [{ json: { ...d, userContent } }];

const gpt = $input.first().json;
const prev = $('Obtener Contenido').first().json;
let d = {};
try {
  d = JSON.parse(gpt.choices[0].message.content);
} catch(e) {
  d = {
    titulo: prev.title || 'Noticia de General Pinto',
    caption_instagram: '📰 ' + prev.title + '\n\n#GeneralPinto #Noticias #BsAs',
    caption_facebook: prev.title + '\n\n' + (prev.bodyText || '').substring(0, 300),
    prompt_imagen: 'Professional news photo, Argentine context, photorealistic: ' + prev.title,
    categoria: 'Sociedad'
  };
}
return [{ json: {
  ...d,
  featuredImage: prev.featuredImage || '',
  externalPhotoUrl: prev.externalPhotoUrl || '',
  sourceUrl: prev.sourceUrl || '',
  source: prev.source || '',
  chatId: prev.chatId,
  contentType: prev.contentType,
  needsImage: prev.contentType !== 'photo' && !prev.featuredImage
} }];

const d = $input.first().json;
const prompt = d.prompt_imagen || 'Professional news illustration, Argentina, realistic photo style';
const PIAPI_KEY = 'a6d29c06675da41c8d28f561a71ca93a944b5454051275c9f3cad81cc7768ddd';

let imageUrl = '';
try {
  // 1. Crear tarea de generacion
  const submitResp = await fetch('https://api.piapi.ai/api/v1/task', {
    method: 'POST',
    headers: {
      'x-api-key': PIAPI_KEY,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'Qubico/flux1-schnell',
      task_type: 'txt2img',
      input: { prompt, width: 1024, height: 1024 }
    })
  });
  const submitData = await submitResp.json();
  const taskId = submitData.data?.task_id;

  if (taskId) {
    // 2. Polling hasta completar (max 60 segundos)
    for (let i = 0; i < 30; i++) {
      await new Promise(r => setTimeout(r, 2000));
      const pollResp = await fetch('https://api.piapi.ai/api/v1/task/' + taskId, {
        headers: { 'x-api-key': PIAPI_KEY }
      });
      const pollData = await pollResp.json();
      const status = pollData.data?.status;
      if (status === 'Completed') {
        imageUrl = pollData.data?.output?.image_url ||
                   pollData.data?.output?.image_urls?.[0] || '';
        break;
      }
      if (status === 'Failed') break;
    }
  }
} catch(e) {
  imageUrl = '';
}

return [{ json: { data: [{ url: imageUrl }] } }];

const dalle = $input.first().json;
const prev = $('Procesar GPT').first().json;

const directUrl = dalle?.data?.[0]?.url || '';

// Prioridad: foto de Telegram > og:image del articulo > URL directa de DALL-E
// La b64 de gpt-image-1 no tiene URL publica, se omite
let finalImageUrl = prev.externalPhotoUrl || prev.featuredImage || directUrl || '';

return [{ json: { ...prev, finalImageUrl, hasImage: !!finalImageUrl } }];

const d = $input.first().json;
const blotatoCaption = d.caption_instagram || d.titulo || 'Noticias de General Pinto';

// Normalizar URL de imagen para que Instagram acepte el aspect ratio
let imgUrl = d.finalImageUrl || '';
if (imgUrl.startsWith('http')) {
  if (imgUrl.includes('i0.wp.com') || imgUrl.includes('.wp.com')) {
    // WordPress/Jetpack: forzar recorte cuadrado 1080x1080 (1:1 - valido para Instagram)
    imgUrl = imgUrl.split('?')[0] + '?resize=1080%2C1080&ssl=1';
  } else if (imgUrl.includes('?fit=') || imgUrl.includes('?resize=')) {
    // Otras URLs con resize params: quitar para usar imagen original
    imgUrl = imgUrl.split('?')[0];
  }
}

const blotatoImageUrl = imgUrl;
return [{ json: { ...d, blotatoCaption, blotatoImageUrl } }];

const blotatoResp = $input.first().json;
const prev = $('Preparar Blotato').first().json;
const igResult = blotatoResp?.error ? { error: blotatoResp.error } : blotatoResp;
return [{ json: { ...prev, igResult } }];

const d = $input.first().json;
const ig = d.igResult || {};
const submitId = ig?.postSubmissionId || ig?.id || ig?.postId || ig?.success;
const ok = submitId ? '✅ Instagram: Publicado' : '⚠️ Instagram: ' + JSON.stringify(ig);
const hora = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });
const msg = '🗞 Portal General Pinto

' + (d.titulo || '') + '
' + (d.categoria || '') + ' - ' + (d.source || '') + '

' + ok + '

' + hora;
return [{ json: { chatId: d.chatId, message: msg } }];
